                    simpleExplanation = "👨‍🏫 توضیح و یاد دادن به زبان خودمانی (چطور مفاهیم گام ۱ و ۲ رو قاطی نکنیم؟):\n• تا اینجا در گام اول با «پیوند مقدس و سه سؤال درس» و در گام دوم با «انتخاب همسر و معیارهای همسر شایسته» آشنا شدیم. حالا دو بخش مهم دیگر درس را یاد بگیر و با هم مقایسه کن:\n• راه‌های شناخت همسر: تحقیق درباره همسر آینده را نباید با معاشرت‌هایی که منشأ آن تنها هوس‌های زودگذر است، اشتباه کرد. تجربه نشان داده است که این‌گونه معاشرت‌ها، هرچند با عنوان‌هایی مانند شناخت روحیه همسر و امتحان او باشد، نتیجه‌بخش نیست و آثار زیانباری دارد که به خاطر همان آثار، خداوند اجازه این‌گونه معاشرت‌ها را به ما نداده است. در این معاشرت‌ها، معمولاً احساسات بر هر دو نفر حاکم می‌شود و دختر و پسر شخصیت واقعی خود را پنهان می‌کنند. هر طرف اصرار دارد خود را بهتر از آنچه هست، نشان دهد تا محبوب دیگری واقع شود. معمولاً هم بیشتر این معاشرت‌ها به سستی رابطه و جدایی می‌انجامند. متناسب با فرهنگ اسلامی، راه‌های زیر برای شناخت کسی که تصمیم به ازدواج با او را داریم، پیشنهاد می‌شود: ۱) تحقیق درباره خانواده همسر و موقعیت اعضای خانواده در محل زندگی و محل کار؛ ۲) شناخت دوستان همسر و کسانی که او با آنها معاشرت بیشتری دارد؛ ۳) تحقیق درباره روحیات و خلقیات همسر در محیط کار یا محل تحصیل؛ ۴) معاشرت خانواده‌های دوطرف با یکدیگر و بهره بردن از تجارب پدر و مادر در این معاشرت‌ها؛ ۵) مشورت با افراد قابل اعتماد و کاردان؛ ۶) گفت‌وگو با یکدیگر در جلسات حضوری و طرح نظرات و دیدگاه‌ها درباره موضوعات مختلف. بهتر است مسیر شناخت همسر با مشارکت پدر و مادر طی شود که سرشار از تجربه‌اند و معمولاً به مصلحت آینده فرزند خود علاقه‌مندند.\n• زمان ازدواج: آمادگی برای ازدواج، نیازمند دو بلوغ است: یکی بلوغ جنسی و دیگری بلوغ عقلی و فکری که مدتی پس از بلوغ جنسی فرا می‌رسد. با رسیدن بلوغ عقلی، جوان درمی‌یابد که باید زندگی را بسیار جدی بگیرد و برای آینده‌اش برنامه‌ریزی کند. توجه به داشتن شغل و پیداکردن کار، فکرکردن درباره ویژگی‌های همسر، تنظیم خرج و هزینه خود و دوری از بی‌برنامه بودن از نشانه‌های بلوغ عقلی است. نباید فاصله میان بلوغ جنسی و عقلی با زمان ازدواج زیاد شود و تشکیل خانواده به تأخیر افتد. به همین علت، پیشوایان ما همواره دختران و پسران را به ازدواج تشویق و ترغیب کرده و از پدران و مادران خواسته‌اند که با کنار گذاشتن رسوم غلط شرایط لازم را برای آنان فراهم کنند و به خاطر پندارهای باطل همچون فراهم شدن همه امکانات زندگی، فرزندان خود را به گناه نکشانند و جامعه را گرفتار آسیب نسازند.\n• پیامبر اکرم می‌فرماید: «کسی که ازدواج کند، نصف دین خود را حفظ کرده است؛ پس باید برای نصف دیگر، از خدا پروا داشته باشد» (اصول کافی، کلینی، ج ۵، ص ۳۲۹؛ من لا یحضره الفقیه، صدوق، ج ۳، ص ۳۸۳). این جمله کوتاه، اهمیت ازدواج را به خوبی می‌رساند و نشان می‌دهد که چگونه نیمی از دینداری انسان با ازدواج، حفظ و نگه‌داری می‌شود. ایشان همچنین می‌فرماید: «برای دختران و پسران خود امکان ازدواج فراهم کنید تا خداوند اخلاقشان را نیکو کند و در رزق و روزی آنها توسعه دهد و عفاف و غیرت آنها را زیاد گرداند» (نوادر، قطب راوندی، ص ۳۶). امام صادق نیز می‌فرماید: «دو رکعت نماز شخص متأهل، برتر از هفتاد رکعت نمازی است که شخص مجرد می‌خواند» (کافی، کلینی، ج ۵، ص ۳۲۸؛ من لا یحضره الفقیه، صدوق، ج ۳، ص ۳۸۴).\n• نباید از یاد ببریم که ازدواج برای رفع نیازهای طبیعی و پاسخ‌گویی به قانون خلقت انجام می‌شود و شایسته است که به این نیازهای طبیعی در «زمان مناسب» و به «شیوه صحیح» پاسخ دهیم. شادابی، سلامت جسمی و روحی، رشد طبیعی، احساس رضایت درونی، کاهش فشار جنسی و سلامت اخلاقی جامعه از فواید ازدواج در «زمان مناسب» است. تأخیر در ازدواج، سبب افزایش فشارهای روحی و روانی، روابط نامشروع و آسیب‌های اجتماعی می‌شود.\n• همچنین اگر فردی بخواهد به شیوه‌ای غیر از شیوه‌های مطرح شده از سوی دین، یعنی به «شیوه ناصحیح» به نیاز جنسی خود پاسخ دهد، در آن صورت، لذت آنی برخاسته از گناه، پس از چندی، روح و روان فرد را پژمرده می‌کند و شخصیت او را می‌شکند. این‌گونه اشخاص، به جای بازگشت به مسیر درست، برای فرار از این پژمردگی به افراط در گناه کشیده می‌شوند؛ اما نمی‌دانند که روحشان مانند تشنه‌ای است که هرچه بیشتر از آب شور دریا می‌نوشد، بر تشنگی‌اش افزوده می‌شود و بیقراری‌اش شدت می‌یابد.\n• و اگر هنوز امکان ازدواج پیدا نکرده‌ای، راه قرآن، عفاف است؛ خداوند در سوره نور، آیه ۳۳ می‌فرماید کسانی که امکان ازدواج برایشان نیست، عفاف پیش گیرند تا خداوند از فضل خود نیاز آنان را برطرف سازد؛ و برای اینکه حفظ عفاف و مهار نفس آسان‌تر شود، می‌توان از اقدامات ده‌گانه‌ای که در درس قبل پیشنهاد شد، استفاده کرد.\n• رازِ یادگیری عمیق اینه که به جای حفظ کردن جداگانه، «مرزِ تفاوت» رو بشناسی:\n  ۱) شش راه شناخت همسر (تحقیق درباره خانواده؛ شناخت دوستان؛ تحقیق درباره روحیات در محیط کار یا تحصیل؛ معاشرت خانواده‌های دوطرف؛ مشورت با افراد قابل اعتماد؛ گفت‌وگو در جلسات حضوری) با معاشرت‌های هوس‌آلود فرق دارد؛ معاشرت هوس‌آلود، راه شناخت نیست و به سستی رابطه و جدایی می‌انجامد.\n  ۲) دو بلوغ: بلوغ جنسی و بلوغ عقلی و فکری؛ بلوغ عقلی، مدتی پس از بلوغ جنسی فرا می‌رسد و نشانه‌های آن، جدی گرفتن زندگی، برنامه‌ریزی برای آینده، توجه به شغل و فکرکردن درباره ویژگی‌های همسر است.\n  ۳) «زمان مناسب» و «شیوه صحیح»: ازدواج در زمان مناسب، شادابی و سلامت جسمی و روحی و رضایت درونی می‌آورد؛ تأخیر در ازدواج، فشارهای روحی و روانی و روابط نامشروع و آسیب‌های اجتماعی می‌آورد؛ و پاسخ به نیاز جنسی به شیوه ناصحیح، روح را پژمرده می‌کند، مثل تشنه‌ای که آب شور دریا می‌نوشد.\n• با این دسته‌بندی ذهنی، هم جواب تشریحی امتحان نهایی رو کامل می‌نویسی و هم توی تست بین دو گزینه شک نمی‌کنی.",
                    visualDiagramText = "┌── جدول مقایسه‌ای درس: راه‌های شناخت همسر و زمان ازدواج ──┐\n│ معاشرت‌های هوس‌آلود ⬅ راه شناخت نیست؛ احساسات بر هر دو نفر حاکم می‌شود؛ دختر و پسر شخصیت واقعی خود را پنهان می‌کنند؛ معمولاً به سستی رابطه و جدایی می‌انجامد\n│ شش راه شناخت همسر ⬅ ۱) تحقیق درباره خانواده همسر و موقعیت اعضای خانواده در محل زندگی و محل کار؛ ۲) شناخت دوستان همسر؛ ۳) تحقیق درباره روحیات و خلقیات همسر در محیط کار یا محل تحصیل؛ ۴) معاشرت خانواده‌های دوطرف با یکدیگر؛ ۵) مشورت با افراد قابل اعتماد و کاردان؛ ۶) گفت‌وگو با یکدیگر در جلسات حضوری؛ بهتر است مسیر شناخت با مشارکت پدر و مادر طی شود\n│ دو بلوغ ⬅ بلوغ جنسی و بلوغ عقلی و فکری؛ بلوغ عقلی، مدتی پس از بلوغ جنسی فرا می‌رسد؛ نشانه‌ها: جدی گرفتن زندگی، برنامه‌ریزی برای آینده، توجه به شغل، فکرکردن درباره ویژگی‌های همسر، تنظیم خرج و هزینه\n│ حدیث نصف دین ⬅ «کسی که ازدواج کند، نصف دین خود را حفظ کرده است؛ پس باید برای نصف دیگر، از خدا پروا داشته باشد» (اصول کافی، ج ۵، ص ۳۲۹؛ من لا یحضره الفقیه، ج ۳، ص ۳۸۳)\n│ حدیث دو رکعت ⬅ «دو رکعت نماز شخص متأهل، برتر از هفتاد رکعت نمازی است که شخص مجرد می‌خواند» (کافی، ج ۵، ص ۳۲۸؛ من لا یحضره الفقیه، ج ۳، ص ۳۸۴)\n│ فواید ازدواج در زمان مناسب ⬅ شادابی، سلامت جسمی و روحی، رشد طبیعی، احساس رضایت درونی، کاهش فشار جنسی، سلامت اخلاقی جامعه\n│ تأخیر در ازدواج ⬅ افزایش فشارهای روحی و روانی، روابط نامشروع، آسیب‌های اجتماعی\n│ شیوه ناصحیح ⬅ لذت آنی گناه، روح را پژمرده می‌کند؛ مثل تشنه‌ای که هرچه بیشتر آب شور دریا می‌نوشد، تشنگی‌اش بیشتر می‌شود\n│ اگر امکان ازدواج نیست ⬅ عفاف پیش بگیر (نور ۳۳) و از اقدامات ده‌گانه درس ۱۷ استفاده کن\n└── نتیجه: شناخت درست با شش راه اسلامی؛ ازدواج در زمان مناسب با دو بلوغ ──┘",
